<script setup lang="ts">
import {computed,ref,onMounted} from 'vue';
import {Download,Printer,Check,ChevronRight,BookOpen} from '@lucide/vue';
import BuildAppearance from './BuildAppearance.vue';
import type {BuildAppearancePlan} from './BuildAppearance.vue';
type Piece={id:string;name:string;file:string;settings:Record<string,string>};
type Plate={index:number;title:string;colour:string;preview:string;parts:Piece[]};
type Project={id:string;label:string;machine:string;file:string;bedMm:number[];nozzleMm:number;bedType:string;status:string;nativeValidation:string;plates:Plate[];sliceSummary?:{estimatedGrams:number;estimatedHours:number;warnings:string[]}};
export type PrintPlan={schemaVersion:number;artifactRevision?:number;status:string;projects:Project[];notes:string[]};
const props=defineProps<{plan:PrintPlan;base:string;buildId:string;appearance?:BuildAppearancePlan}>();
const emit=defineEmits<{assemble:[]}>();
const chosen=ref(''),done=ref<string[]>([]);
const current=computed(()=>props.plan.projects.find(p=>p.id===chosen.value));
const coloured=computed(()=>!!props.appearance&&current.value?.id==='h2c');
const plateColour=(colour:string)=>coloured.value?(colour==='red'?'灰烬红 · A1 / PLA Silk':'冰白 · A4 / PLA Basic'):(colour==='red'?'红色 PLA':'黑色 PLA');
const nativeStatus=computed(()=>current.value?.nativeValidation==='PASSED'?'本地切片检查已通过':current.value?.nativeValidation==='SLICED_WITH_WARNINGS'?'本地各盘切片已完成，存在厂家指令解析警告，打印前仍须预览复核':current.value?.nativeValidation==='IMPORTED'?'已通过本地切片器导入检查，尚未完整切片':'已自动排盘，尚待原生切片检查');
const file=(name:string)=>props.base+'/files/'+name;
const key=computed(()=>props.buildId+'-print-progress-v1');
const record=(name:string)=>{done.value=done.value.includes(name)?done.value.filter(s=>s!==name):[...done.value,name];try{localStorage.setItem(key.value,JSON.stringify({project:chosen.value,done:done.value}));}catch{/* storage optional */}};
function choose(){done.value=[];try{localStorage.setItem(key.value,JSON.stringify({project:chosen.value,done:[]}));}catch{/* storage optional */}}
onMounted(()=>{try{const data=JSON.parse(localStorage.getItem(key.value)||'{}');if(props.plan.projects.some(p=>p.id===data.project)){chosen.value=data.project;done.value=Array.isArray(data.done)?data.done.filter((x:unknown)=>typeof x==='string'):[];}}catch{/* ignore old local state */}});
</script>

<template>
  <section class="plate-studio">
    <header class="plate-intro"><span>PRINT, WITHOUT THE GUESSWORK</span><h1>一份工程。每一盘，都排好了。</h1><p>不用逐个拖 STL、不用自己摆盘。选择实际机型，打开整套 3MF；先打印试片，再按盘换颜色，最后跟着动画装配。</p></header>
    <div class="plate-flow"><span><b>1</b>选择机型</span><ChevronRight :size="14"/><span><b>2</b>打开整套工程</span><ChevronRight :size="14"/><span><b>3</b>试片 → 分盘打印</span><ChevronRight :size="14"/><span><b>4</b>跟着装配</span></div>
    <div class="plate-choice"><label for="plate-printer">你的打印机 · 不预设机型</label><select id="plate-printer" v-model="chosen" @change="choose"><option value="">请选择打印机</option><option v-for="p in plan.projects" :key="p.id" :value="p.id">{{p.label}}</option><option value="other">其他机型 / 喷嘴不是 0.4 mm</option></select><p>这些工程使用 0.4 mm 喷嘴、PLA、纹理 PEI 板。实际配置不同，请先在切片器中切换并重新切片。</p></div>
    <div v-if="chosen==='other'" class="plate-notice" role="status">不把其他机型的打印代码交给你。请先确认实际机型、热床尺寸和喷嘴；下方单件文件仅作高级备用，不要缩小模型来适配热床。</div>
    <template v-if="current">
      <BuildAppearance v-if="coloured&&appearance" :plan="appearance" :base="base"/>
      <p v-if="(plan.artifactRevision||1)>=2" class="plate-notice" role="status"><strong>3MF 修订版 R{{plan.artifactRevision}}。</strong>已修正耗材变体映射及填充图案兼容问题。如旧文件提示“没有几何数据”，请重新下载下方文件名含 <code>-r{{plan.artifactRevision}}.3mf</code> 的工程，不要继续打开旧下载。</p>
      <div class="plate-project" :data-printer="current.id"><div><span>{{current.label}} · {{current.plates.length}} 盘 · 单料槽</span><h2>{{coloured?'原始通用排盘工程（备用）':'整套红黑 PLA 排盘工程'}}</h2><p>{{coloured?'本机灰烬红／冰白方案请用上方两份工程。此处保留原版 Generic PLA 预设，不含当前丝绸料配置。':'18 个打印件＋1 个试片，每件只出现一次。红黑分盘，不需要 AMS；只在盘与盘之间更换耗材。'}}</p></div><a class="plate-primary" :href="file(current.file)" download><Download :size="18"/>{{coloured?'下载原版备用 3MF':'下载整套 3MF'}}</a></div>
      <p class="plate-notice" role="status"><strong>{{nativeStatus}}。</strong>下载文件仍是可编辑、未切片工程，不含已切片的打印路径，也不会启动打印机。采购件尺寸、公差和实物打印尚待核对。</p>
      <p v-if="current.sliceSummary" class="plate-notice">当前测试预设估算：{{current.sliceSummary.estimatedGrams}} g / {{current.sliceSummary.estimatedHours}} 小时（含试片、支撑和裙边，非实测；指令解析警告也可能影响估时）。H2C 建议先预留{{coloured?"白色 PLA Basic 300 g、灰烬红 PLA Silk 250 g":"黑 PLA 300 g、红 PLA 250 g"}}，最终以实际耗材预设重新切片为准。</p>
      <div class="plate-how"><h2>第一次使用，照这 6 步做</h2><ol><li>安装并打开 Bambu Studio。选择 <b>文件 → 打开项目</b>，打开刚下载的 <code>.3mf</code>；若询问导入方式，选择<b>作为项目打开</b>，不要只导入几何。</li><li>左上确认 <b>{{current.label}} / 0.4 mm / 纹理 PEI 板</b>，耗材改成手中 PLA 的实际预设。不要改比例，也不要再次自动朝向。</li><li>先只选第 1 盘公差试片，装{{coloured?"A4 白色 PLA Basic":"黑 PLA"}}，点<b>切片单盘</b>。预览没有越界、悬空或碰撞警告才继续。</li><li>你确认设备、耗材和首层后，自己点打印。试片冷却取下，用 M3 螺钉和 693ZZ 轴承试配；不合适先校准，别整车缩放。</li><li>确认电机、轮子、电池盒和降压板的实物尺寸，再依次打印剩下各盘；每盘核对下面的颜色，清空上一盘后再开打。</li><li>冷却后拆支撑、修净毛刺，按盘装袋、逐项清点。小隔套别扔掉。零件齐了点击“开始装配”。</li></ol><a :href="file('instructions.html')+'#printing'" target="_blank"><BookOpen :size="16"/>详细图文教程、烧录及故障排查 ↗</a></div>
      <div class="plate-grid"><article v-for="plate in current.plates" :key="current.id+plate.index" class="plate-card"><div class="plate-card-head"><strong>{{plate.index===1?'先试配':'第 '+plate.index+' 盘'}}</strong><span :class="plate.colour">{{plateColour(plate.colour)}}</span></div><img :src="file(plate.preview)" :alt="plate.title+'：打印件俯视占位示意'" loading="lazy"/><small>俯视占位示意 · 不是支撑 / G-code 预览</small><h3>{{coloured?'第 '+plate.index+' 盘 · '+plateColour(plate.colour):plate.title}}</h3><ol><li v-for="p in plate.parts" :key="p.id">{{p.name}}<small>{{p.id}} · {{p.settings.sparse_infill_density}} 填充 · {{p.settings.enable_support==='1'?'已设自动树状支撑':'无需自动支撑'}}</small></li></ol><label><input type="checkbox" :checked="done.includes(current.id+'-'+plate.index)" @change="record(current.id+'-'+plate.index)"/>我已打印、清点并试配这一盘</label></article></div>
      <div class="plate-finish"><span><Check :size="16"/>{{done.filter(x=>x.startsWith(chosen+'-')).length}} / {{current.plates.length}} 盘由你标记完成；不是自动验收。</span><button type="button" @click="emit('assemble')">开始装配 <ChevronRight :size="16"/></button></div>
    </template>
    <p v-else-if="!chosen" class="plate-empty"><Printer :size="28"/>先选机型，再给你对应的整套排盘文件。不会默认替你选 H2C。</p>
  </section>
</template>

<style scoped>
.plate-studio{max-width:1120px}.plate-intro>span{font-size:10px;letter-spacing:.15em;color:#ec7d90}.plate-intro h1{font-size:clamp(26px,3.3vw,42px);letter-spacing:-.045em;line-height:1.2;margin:14px 0}.plate-intro p,.plate-choice p,.plate-project p{font-size:13px;line-height:1.85;color:#acb7c9;max-width:720px}.plate-flow{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:23px 0;color:#a8b7c9;font-size:11px}.plate-flow span{display:flex;align-items:center;gap:7px}.plate-flow b{border:1px solid #8fa2c533;border-radius:50%;padding:4px 8px;color:#ecf3ff}.plate-choice{background:#151b26;border:1px solid #c4d4ff19;padding:18px;border-radius:14px}.plate-choice label{display:block;font-size:12px;margin-bottom:9px}.plate-choice select{width:100%;max-width:430px;padding:11px;border-radius:8px;border:1px solid #869bb54d;background:#0d1420;color:#edf3ff}.plate-choice p{font-size:11px;margin:9px 0 0}.plate-project{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:24px}.plate-project span{font-size:11px;color:#9fb1c8}.plate-project h2{font-size:23px;margin:9px 0}.plate-primary,.plate-finish button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px 18px;border:0;border-radius:10px;background:#dd3854;color:white!important;text-decoration:none;font-size:13px;white-space:nowrap;cursor:pointer}.plate-notice{background:#a9802020;border:1px solid #cbac6440;border-radius:10px;padding:13px 15px;color:#d5c5a6;font-size:12px;line-height:1.9}.plate-how{margin:25px 0;padding:20px;border:1px solid #9dacc326;border-radius:14px}.plate-how h2{font-size:17px;margin:0 0 12px}.plate-how ol{padding-left:22px;line-height:1.9;font-size:13px;color:#b5c1d2}.plate-how li{padding:5px 0}.plate-how a{color:#a4c7fc;display:flex;gap:8px;align-items:center;text-decoration:none;font-size:12px}.plate-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:18px}.plate-card{padding:17px;border:1px solid #a7bed022;border-radius:15px;background:#131923}.plate-card-head{display:flex;justify-content:space-between;align-items:center;font-size:12px}.plate-card-head span{padding:5px 9px;border-radius:30px;background:#8d9db22b}.plate-card-head .red{background:#d9446029;color:#ff9db1}.plate-card img{width:100%;height:225px;object-fit:contain;margin-top:15px}.plate-card>small{display:block;text-align:center;color:#778ba5;font-size:10px}.plate-card h3{font-size:14px}.plate-card ol{padding-left:20px;font-size:12px;line-height:1.7}.plate-card li>small{display:block;color:#8699b2;font-size:10px}.plate-card label{display:flex;gap:8px;align-items:flex-start;border-top:1px solid #819bbf22;padding-top:13px;font-size:11px;line-height:1.8}.plate-finish{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:24px 0}.plate-finish span{display:flex;gap:6px;font-size:11px;color:#97aac2}.plate-empty{display:flex;align-items:center;gap:16px;padding:35px 0;color:#9dacbf;font-size:13px}@media(max-width:650px){.plate-project,.plate-finish{align-items:stretch;flex-direction:column}.plate-card img{height:200px}}
</style>

